<?php
require __DIR__ . '/config.php';
function e($v) { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
$error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $action = $_POST['action'] ?? '';
    if ($action === 'save') {
        $id = (int)($_POST['id'] ?? 0);
        $name = trim($_POST['name'] ?? ''); $sku = trim($_POST['sku'] ?? '');
        $category = trim($_POST['category'] ?? ''); $supplier = trim($_POST['supplier'] ?? '');
        $quantity = max(0, (int)($_POST['quantity'] ?? 0)); $price = max(0, (float)($_POST['price'] ?? 0));
        $reorder = max(0, (int)($_POST['reorder_level'] ?? 5));
        if ($name === '' || $sku === '') { $error = 'Product name and SKU are required.'; }
        else if ($id > 0) {
            $stmt = $conn->prepare('UPDATE products SET name=?, sku=?, category=?, supplier=?, quantity=?, price=?, reorder_level=? WHERE id=?');
            $stmt->bind_param('ssssiddi', $name,$sku,$category,$supplier,$quantity,$price,$reorder,$id);
            if (!$stmt->execute()) $error = 'Could not update product. Check that SKU is unique.';
            $stmt->close();
        } else {
            $stmt = $conn->prepare('INSERT INTO products (name,sku,category,supplier,quantity,price,reorder_level) VALUES (?,?,?,?,?,?,?)');
            $stmt->bind_param('ssssidi', $name,$sku,$category,$supplier,$quantity,$price,$reorder);
            if (!$stmt->execute()) $error = 'Could not add product. Check that SKU is unique.';
            $stmt->close();
        }
        if ($error === '') { header('Location: index.php'); exit; }
    } elseif ($action === 'delete') {
        $id = (int)($_POST['id'] ?? 0); $stmt = $conn->prepare('DELETE FROM products WHERE id=?');
        $stmt->bind_param('i',$id); $stmt->execute(); $stmt->close(); header('Location: index.php'); exit;
    }
}
$edit = null;
if (isset($_GET['edit'])) { $id=(int)$_GET['edit']; $stmt=$conn->prepare('SELECT * FROM products WHERE id=?'); $stmt->bind_param('i',$id); $stmt->execute(); $edit=$stmt->get_result()->fetch_assoc(); $stmt->close(); }
$search = trim($_GET['q'] ?? '');
if ($search !== '') { $like='%'.$search.'%'; $stmt=$conn->prepare('SELECT * FROM products WHERE name LIKE ? OR sku LIKE ? OR category LIKE ? ORDER BY id DESC'); $stmt->bind_param('sss',$like,$like,$like); $stmt->execute(); $products=$stmt->get_result(); }
else { $products=$conn->query('SELECT * FROM products ORDER BY id DESC'); }
$stats=$conn->query('SELECT COUNT(*) items, COALESCE(SUM(quantity),0) units, COALESCE(SUM(quantity*price),0) value, COALESCE(SUM(quantity<=reorder_level),0) low FROM products')->fetch_assoc();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>StockWise | Inventory Management</title><style>
:root{--ink:#172033;--muted:#697386;--line:#e5e9f0;--bg:#f5f7fb;--blue:#3157d5;--green:#13795b;--red:#b42318}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 Arial,sans-serif}.top{background:#fff;border-bottom:1px solid var(--line);padding:18px max(20px,calc((100% - 1180px)/2));display:flex;justify-content:space-between;align-items:center}.brand{font-size:22px;font-weight:800}.brand span{color:var(--blue)}.tag{color:var(--muted);font-size:13px}.wrap{max-width:1180px;margin:28px auto;padding:0 18px}.heading{display:flex;justify-content:space-between;align-items:end;gap:15px;flex-wrap:wrap}.heading h1{margin:0;font-size:28px}.muted{color:var(--muted)}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:22px 0}.card,.panel{background:#fff;border:1px solid var(--line);border-radius:13px;padding:19px;box-shadow:0 4px 18px #17203308}.label{color:var(--muted);font-size:13px}.num{font-size:25px;font-weight:750;margin-top:6px}.lowtext{color:var(--red)}.layout{display:grid;grid-template-columns:330px 1fr;gap:16px}.panel h2{font-size:18px;margin:0 0 16px}.field{margin-bottom:12px}.field label{display:block;font-size:13px;font-weight:700;margin-bottom:5px}.field input{width:100%;padding:10px 11px;border:1px solid #d8deea;border-radius:8px;font:inherit}.btn{border:0;border-radius:8px;padding:10px 13px;background:var(--blue);color:#fff;font-weight:700;cursor:pointer;text-decoration:none;display:inline-block}.btn.secondary{background:#eef2ff;color:#2948b8}.btn.danger{background:#fff0ef;color:var(--red);padding:7px 9px}.actions{display:flex;gap:7px;align-items:center}.search{display:flex;gap:8px;margin-bottom:14px}.search input{flex:1;min-width:90px;padding:10px;border:1px solid #d8deea;border-radius:8px}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap}th,td{text-align:left;border-bottom:1px solid var(--line);padding:12px 9px;font-size:13px}th{color:var(--muted);font-weight:700;background:#fafbfe}.pill{display:inline-block;border-radius:20px;padding:4px 8px;background:#e8f7ef;color:var(--green);font-size:12px}.pill.low{background:#fff0ef;color:var(--red)}.alert{background:#fff4e5;color:#8a4b08;border:1px solid #ffdfad;padding:10px;border-radius:8px;margin-bottom:12px}.empty{padding:25px;text-align:center;color:var(--muted)}footer{text-align:center;color:var(--muted);padding:25px;font-size:12px}@media(max-width:850px){.cards{grid-template-columns:repeat(2,1fr)}.layout{grid-template-columns:1fr}}@media(max-width:450px){.cards{grid-template-columns:1fr 1fr}.heading h1{font-size:23px}}
</style></head><body><header class="top"><div><div class="brand">Stock<span>Wise</span></div><div class="tag">Inventory &amp; Supply Management</div></div><span class="tag">Demo project · PHP + MySQL</span></header><main class="wrap"><div class="heading"><div><h1>Inventory overview</h1><div class="muted">Manage products, quantities and reorder levels.</div></div><a class="btn" href="#product-form">+ Add product</a></div><section class="cards"><div class="card"><div class="label">Products</div><div class="num"><?= (int)$stats['items'] ?></div></div><div class="card"><div class="label">Units in stock</div><div class="num"><?= (int)$stats['units'] ?></div></div><div class="card"><div class="label">Stock value</div><div class="num">₹<?= number_format((float)$stats['value'],2) ?></div></div><div class="card"><div class="label">Low-stock items</div><div class="num lowtext"><?= (int)$stats['low'] ?></div></div></section>
<?php if($error): ?><div class="alert"><?=e($error)?></div><?php endif; ?>
<div class="layout"><section class="panel" id="product-form"><h2><?= $edit ? 'Edit product' : 'Add a product' ?></h2><form method="post"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><div class="field"><label>Product name *</label><input name="name" required maxlength="150" value="<?=e($edit['name']??'')?>" placeholder="e.g. Wireless Mouse"></div><div class="field"><label>SKU / Product code *</label><input name="sku" required maxlength="60" value="<?=e($edit['sku']??'')?>" placeholder="e.g. ACC-001"></div><div class="field"><label>Category</label><input name="category" value="<?=e($edit['category']??'')?>" placeholder="Accessories"></div><div class="field"><label>Supplier</label><input name="supplier" value="<?=e($edit['supplier']??'')?>" placeholder="Supplier name"></div><div class="field"><label>Quantity</label><input type="number" name="quantity" min="0" value="<?=e($edit['quantity']??0)?>"></div><div class="field"><label>Unit price (₹)</label><input type="number" step="0.01" min="0" name="price" value="<?=e($edit['price']??0)?>"></div><div class="field"><label>Low-stock alert level</label><input type="number" min="0" name="reorder_level" value="<?=e($edit['reorder_level']??5)?>"></div><button class="btn" type="submit"><?= $edit ? 'Save changes' : 'Add product' ?></button> <?php if($edit): ?><a class="btn secondary" href="index.php">Cancel</a><?php endif; ?></form></section>
<section class="panel"><h2>Products &amp; stock</h2><form class="search" method="get"><input name="q" value="<?=e($search)?>" placeholder="Search name, SKU or category"><button class="btn" type="submit">Search</button><a class="btn secondary" href="index.php">Reset</a></form><div class="tablewrap"><table><thead><tr><th>Product</th><th>SKU</th><th>Category</th><th>Qty</th><th>Unit price</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if($products && $products->num_rows): while($p=$products->fetch_assoc()): ?><tr><td><strong><?=e($p['name'])?></strong><br><span class="muted"><?=e($p['supplier'])?></span></td><td><?=e($p['sku'])?></td><td><?=e($p['category'])?></td><td><?= (int)$p['quantity'] ?></td><td>₹<?=number_format((float)$p['price'],2)?></td><td><span class="pill <?=((int)$p['quantity'] <= (int)$p['reorder_level'])?'low':''?>"><?=((int)$p['quantity'] <= (int)$p['reorder_level'])?'Low stock':'In stock'?></span></td><td><div class="actions"><a class="btn secondary" href="?edit=<?=(int)$p['id']?>">Edit</a><form method="post" onsubmit="return confirm('Delete this product?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><button class="btn danger" type="submit">Delete</button></form></div></td></tr><?php endwhile; else: ?><tr><td colspan="7" class="empty">No products found. Add your first product using the form.</td></tr><?php endif; ?></tbody></table></div></section></div></main><footer>StockWise Inventory Management · Built with PHP, MySQL, HTML and CSS</footer></body></html>
